mapper.select:
SELECT th.*,
pt.name AS project_name,
pr.ask_item,
pr.question,
u.user_name,
pr.answer AS ask_answer,
pr.right_answer,
pr.practice_type,
pa.id AS paper_id,
pa.name AS paper_name
FROM test_history th
LEFT JOIN practice pr ON pr.id = th.practice_id
LEFT JOIN project_type pt ON pt.id = pr.project_id
LEFT JOIN paper pa ON pa.id = th.paper_id
LEFT JOIN user u ON th.user_id = u.id


        AND th.answer = #{answer}


        AND th.practice_id = #{practiceId}


        AND th.user_id = #{userId}


        AND th.post_score = #{postScore}


        AND th.paper_id = #{paperId}


        AND th.create_time BETWEEN #{startTime} AND #{endTime}


ORDER BY th.id DESC

    LIMIT #{current},#{size}

SELECT COUNT(*)
FROM test_history th


        AND th.answer = #{answer}


        AND th.practice_id = #{practiceId}


        AND th.user_id = #{userId}


        AND th.paper_id = #{paperId}


        AND th.post_score = #{postScore}


